def find_min_arrow_shots(points):
    if not points:
        return 0

    n = len(points)
    burst = [False] * n
    arrows = 0

    for i in range(n):
        if burst[i]:
            continue
        arrows += 1
        arrow_pos = points[i][1]
        for j in range(n):
            if not burst[j] and points[j][0] <= arrow_pos <= points[j][1]:
                burst[j] = True

    return arrows


if __name__ == "__main__":
    print(find_min_arrow_shots([[10, 16], [2, 8], [1, 6], [7, 12]]))
    print(find_min_arrow_shots([[1, 2], [3, 4], [5, 6], [7, 8]]))

