        if (points.length == 0) return 0;

        int[][] sorted = points.clone();
        Arrays.sort(sorted, (a, b) -> Integer.compare(a[1], b[1]));

        int arrows = 1;
        long arrowPos = sorted[0][1];

        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i][0] > arrowPos) {
                arrows++;
                arrowPos = sorted[i][1];
            }
        }
        return arrows;
    }

