#include <bits/stdc++.h>
using namespace std;

int findMinArrowShots(vector<vector<int>>& points) {
    if (points.empty()) return 0;

    vector<vector<int>> sorted = points;
    sort(sorted.begin(), sorted.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    });

    int arrows = 1;
    long long arrowPos = sorted[0][1];

    for (int i = 1; i < (int)sorted.size(); i++) {
        if (sorted[i][0] > arrowPos) {
            arrows++;
            arrowPos = sorted[i][1];
        }
    }
    return arrows;
}

int main() {
    vector<vector<int>> points1 = {{10, 16}, {2, 8}, {1, 6}, {7, 12}};
    cout << findMinArrowShots(points1) << endl;
